#!/usr/bin/env python3
"""Builds podcast_script_simpa{,_fr,_de,_lb}.md from build/simpa_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "simpa"
HEAD = {
 "en": ('# Podcast Script — "SIMPA – Information and Mediation for Older People"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « Le SIMPA – information et médiation pour les personnes âgées »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Der SIMPA – Information und Mediation für ältere Menschen“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „De SIMPA – Informatioun a Mediatioun fir eeler Leit“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 10, "fr": 9, "de": 11, "lb": 10}   # EN 9:53, FR 8:59, DE 10:38 (shortened version, 26 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources: simpa.public.lu (SIMPA – National Information and Mediation Service in the field of services for older people, Ministry of Family Affairs, Solidarity, Living Together and Reception of Refugees), consulted on 26 November 2026 in French and German — home page, \"Information\", \"Seniorentelefon\" (since 1999, International Year of Older Persons; languages; Monday to Friday in the morning), \"Public register of services for older people\", \"Aids\", \"Mediation\" (principles; services concerned; situations outside its remit), \"Course of a mediation\" (individual talks, agreement to mediate, meetings, companions, mediation agreement, example of Mr Muller), \"Request a mediation\", \"Other bodies for settling disputes\", \"Alternatives to mediation\", \"Who we are\" / \"Our missions\" / \"Our values\", \"FAQ\" (all services free of charge; no representation of the parties; confidentiality; appointments), \"Legislation\" (law of 23 August 2023 on the quality of services for older people); mfsva.gouvernement.lu (page on SIMPA); government press release of 25 March 2025 (presentation of SIMPA, integration of the Seniorentelefon); SIMPA's own presentation \"Lunchtalk – from information and support to mediation\" (November 2026: listening, understanding and explaining, strengthening the dialogue; the four ideas of the 2023 quality law; themes of mediations; three things to remember). Durable wording only: no names of the team, no street address, no general phone number, no exact opening hours, no statistics. The number of the Seniorentelefon, 247-86000, is the one given on simpa.public.lu (French and German pages) and guichet.public.lu. The opening scene and the hosts' closing advice are illustrations by the hosts. General information only. Accurate as of November 2026.*",
 "fr": "*Sources : simpa.public.lu (SIMPA – Service national d'information et de médiation dans le domaine des services pour personnes âgées, Ministère de la Famille, des Solidarités, du Vivre ensemble et de l'Accueil), consulté le 26 novembre 2026 en français et en allemand — page d'accueil, « Information », « Seniorentelefon » (depuis 1999, Année internationale des personnes âgées ; langues ; du lundi au vendredi, le matin), « Registre public des services pour personnes âgées », « Aides », « Médiation » (principes ; services concernés ; situations hors compétence), « Déroulement de la médiation » (entretiens individuels préalables, accord en vue de médiation, réunions, accompagnants, accord de médiation, exemple de Monsieur Muller), « Demander une médiation », « Autres instances de règlement de conflits », « Alternatives à la médiation », « Qui sommes-nous ? » / « Nos missions » / « Nos valeurs », « FAQ » (services entièrement gratuits ; pas de représentation des parties ; confidentialité ; rendez-vous), « Législation » (loi du 23 août 2023 sur la qualité des services pour personnes âgées) ; mfsva.gouvernement.lu (page SIMPA) ; communiqué du gouvernement du 25 mars 2025 (présentation du SIMPA, intégration du Seniorentelefon) ; présentation du SIMPA « Lunchtalk – de l'information et de l'accompagnement à la médiation » (novembre 2026 : écouter, comprendre et expliquer, renforcer le dialogue ; les quatre idées de la loi qualité de 2023 ; thèmes des médiations ; trois choses à retenir). Formulations durables uniquement : pas de noms de l'équipe, pas d'adresse, pas de numéro général, pas d'horaires exacts, pas de statistiques. Le numéro du Seniorentelefon, 247-86000, est celui indiqué sur simpa.public.lu (pages française et allemande) et sur guichet.public.lu. La scène d'ouverture et le conseil final des animateurs sont des illustrations des animateurs. Informations générales uniquement. Exact en novembre 2026.*",
 "de": "*Quellen: simpa.public.lu (SIMPA – Nationaler Dienst für Information und Mediation im Bereich der Dienstleistungen für ältere Menschen, Ministerium für Familie, Solidarität, Zusammenleben und Unterbringung von Flüchtlingen), abgerufen am 26. November 2026 auf Französisch und Deutsch — Startseite, „Information“, „Seniorentelefon“ (seit 1999, Internationales Jahr der älteren Menschen; Sprachen; montags bis freitags vormittags), „Öffentliches Register der Dienstleistungen für ältere Menschen“, „Hilfen“, „Mediation“ (Grundsätze; betroffene Dienste; Fälle außerhalb der Zuständigkeit), „Ablauf einer Mediation“ (Einzelgespräche, Vereinbarung über die Mediation, Treffen, Begleitpersonen, Mediationsvereinbarung, Beispiel von Herrn Muller), „Mediationsanfrage“, „Andere Stellen zur Konfliktlösung“, „Alternativen zur Mediation“, „Wer sind wir?“ / „Unsere Aufgaben“ / „Unsere Werte“, „FAQ“ (alle Leistungen kostenlos; keine Vertretung der Parteien; Vertraulichkeit; Termine), „Gesetzgebung“ (Gesetz vom 23. August 2023 über die Qualität der Dienstleistungen für ältere Menschen); mfsva.gouvernement.lu (Seite zum SIMPA); Pressemitteilung der Regierung vom 25. März 2025 (Vorstellung des SIMPA, Eingliederung des Seniorentelefons); Präsentation des SIMPA „Lunchtalk – von Information und Begleitung bis zur Mediation“ (November 2026: zuhören, verstehen und erklären, den Dialog stärken; die vier Ideen des Qualitätsgesetzes von 2023; Themen der Mediationen; drei Dinge zum Merken). Nur dauerhafte Angaben: keine Namen des Teams, keine Adresse, keine allgemeine Telefonnummer, keine genauen Zeiten, keine Statistiken. Die Nummer des Seniorentelefons, 247-86000, ist die auf simpa.public.lu (französische und deutsche Seiten) und auf guichet.public.lu angegebene. Die Eingangsszene und der abschließende Rat der Moderatoren sind Veranschaulichungen der Moderatoren. Nur allgemeine Informationen. Stand: November 2026.*",
 "lb": "*Quellen: simpa.public.lu (SIMPA – Nationale Informatiouns- a Mediatiounsdéngscht fir d'Servicer fir eeler Leit), consultéiert de 26. November 2026 op Franséisch an Däitsch; mfsva.gouvernement.lu; Communiqué vun der Regierung vum 25. Mäerz 2025; Presentatioun vum SIMPA „Lunchtalk – Vun Informatioun a Begleedung bis zur Mediatioun“ (November 2026). Fräi Iwwersetzung: de Site huet keng lëtzebuergesch Versioun. Keng Nimm, keng Adress, keng genau Zäiten a keng Statistiken. Nëmmen allgemeng Informatiounen. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/simpa_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 48, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
